# demo_bdi_scenario()BDI架构的强大之处在于它模拟了人类的实用推理过程。Agent不是机械地执行任务，而是根据信念、欲望和意图做出理性决策。强化学习：让Agent越来越聪明去年最大的收获就是把强化学习用到了实际项目里。虽然训练过程痛苦（GPU烧了两块），但效果是真的好。先说个基础的Q-Learning，这是强化学习的入门算法：import numpy as np
import random
from typing import Tuple, Optional
import matplotlib.pyplot as plt

class QLearningAgent:
    &#34;&#34;&#34;
    Q-Learning Agent
    我第一次实现这个的时候，调参调到怀疑人生

    Q-Learning的核心思想：
    通过不断试错，学习在每个状态下采取哪个动作能获得最大累积奖励
    &#34;&#34;&#34;

    def __init__(self, n_states: int, n_actions: int, 
                 learning_rate: float = 0.1,
                 discount_factor: float = 0.95,
                 epsilon: float = 0.1):

        self.n_states = n_states
        self.n_actions = n_actions
        self.lr = learning_rate        # 学习率，太大会震荡
        self.gamma = discount_factor    # 折扣因子，决定重视未来的程度
        self.epsilon = epsilon          # 探索率，平衡探索和利用

        # Q表，记录每个状态-动作对的价值
        # 初始化成小随机数比全零好，血的教训
        self.q_table = np.random.uniform(low=-0.1, high=0.1, 
                                        size=(n_states, n_actions))

        # 学习历史记录
        self.episode_rewards = []
        self.episode_lengths = []

        print(f&#34;Q-Learning Agent初始化: {n_states}个状态, {n_actions}个动作&#34;)

    def choose_action(self, state: int, training: bool = True) -&gt; int:
        &#34;&#34;&#34;
        ε-贪婪策略选择动作
        训练时要探索，测试时要利用
        &#34;&#34;&#34;
        if training and random.random() &lt; self.epsilon:
            # 探索：随机选择
            action = random.randint(0, self.n_actions - 1)
        else:
            # 利用：选择Q值最大的动作
            action = np.argmax(self.q_table[state])

            # 处理多个最大值的情况（随机选择）
            max_q = np.max(self.q_table[state])
            max_actions = np.where(self.q_table[state] == max_q)[0]
            if len(max_actions) &gt; 1:
                action = np.random.choice(max_actions)

        return action

    def learn(self, state: int, action: int, reward: float, 
             next_state: int, done: bool):
        &#34;&#34;&#34;
        Q-Learning核心：更新Q表
        公式：Q(s,a) ← Q(s,a) + α[r + γ max Q(s&#39;,a&#39;) - Q(s,a)]
        &#34;&#34;&#34;
        # 当前Q值
        current_q = self.q_table[state, action]

        # 计算目标Q值
        if done:
            # 终止状态，没有未来收益
            target_q = reward
        else:
            # Bellman方程：即时奖励 + 折扣后的未来最大收益
            max_next_q = np.max(self.q_table[next_state])
            target_q = reward + self.gamma * max_next_q

        # 更新Q值：渐进式更新，不要太激进
        self.q_table[state, action] += self.lr * (target_q - current_q)

    def decay_epsilon(self, decay_rate: float = 0.995, min_epsilon: float = 0.01):
        &#34;&#34;&#34;
        逐渐减少探索，增加利用
        这个技巧很重要，不然Agent会一直乱试
        &#34;&#34;&#34;
        self.epsilon *= decay_rate
        self.epsilon = max(min_epsilon, self.epsilon)

    def get_policy(self) -&gt; np.ndarray:
        &#34;&#34;&#34;从Q表中提取策略&#34;&#34;&#34;
        return np.argmax(self.q_table, axis=1)

    def save_q_table(self, filepath: str):
        &#34;&#34;&#34;保存Q表&#34;&#34;&#34;
        np.save(filepath, self.q_table)
        print(f&#34;Q表已保存到 {filepath}&#34;)

    def load_q_table(self, filepath: str):
        &#34;&#34;&#34;加载Q表&#34;&#34;&#34;
        self.q_table = np.load(filepath)
        print(f&#34;Q表已从 {filepath} 加载&#34;)但Q-Learning只能处理小规模问题。状态空间一大就爆炸了。所以才有了Deep Q-Network (DQN)，这是DeepMind在2015年Nature论文中提出的[3]：import torch
import torch.nn as nn
import torch.optim as optim
from collections import deque
import numpy as np

class DQN(nn.Module):
    &#34;&#34;&#34;
    深度Q网络
    用神经网络来近似Q函数，能处理连续状态空间

    网络架构：
    - 输入层：状态向量
    - 隐藏层：2层全连接
    - 输出层：每个动作的Q值
    &#34;&#34;&#34;

    def __init__(self, input_size: int, hidden_size: int, output_size: int):
        super(DQN, self).__init__()

        # 三层全连接网络，简单有效
        self.fc1 = nn.Linear(input_size, hidden_size)
        self.fc2 = nn.Linear(hidden_size, hidden_size)
        self.fc3 = nn.Linear(hidden_size, output_size)

        # ReLU激活函数，训练稳定
        self.relu = nn.ReLU()

        # 初始化权重（Xavier初始化）
        nn.init.xavier_uniform_(self.fc1.weight)
        nn.init.xavier_uniform_(self.fc2.weight)
        nn.init.xavier_uniform_(self.fc3.weight)

    def forward(self, x):
        x = self.relu(self.fc1(x))
        x = self.relu(self.fc2(x))
        x = self.fc3(x)
        return x

class DQNAgent:
    &#34;&#34;&#34;
    DQN Agent - 能处理复杂环境
    训练这个要有耐心，我第一次训练花了整整两天

    关键技巧：
    1. 经验回放（Experience Replay）
    2. 目标网络（Target Network）
    3. 双Q学习（Double DQN）
    &#34;&#34;&#34;

    def __init__(self, state_size: int, action_size: int, 
                 learning_rate: float = 0.001,
                 buffer_size: int = 10000,
                 batch_size: int = 32):

        self.state_size = state_size
        self.action_size = action_size
        self.batch_size = batch_size

        # 两个网络：一个学习，一个提供稳定目标
        self.q_network = DQN(state_size, 128, action_size)
        self.target_network = DQN(state_size, 128, action_size)

        # 复制参数到目标网络
        self.update_target_network()

        # 优化器
        self.optimizer = optim.Adam(self.q_network.parameters(), lr=learning_rate)

        # 经验回放池
        self.memory = deque(maxlen=buffer_size)

        # 探索参数
        self.epsilon = 1.0
        self.epsilon_decay = 0.995
        self.epsilon_min = 0.01

        # 训练计数
        self.steps = 0
        self.update_frequency = 4  # 每4步更新一次网络
        self.target_update_frequency = 1000  # 每1000步更新目标网络

        print(f&#34;DQN Agent创建: 输入维度={state_size}, 输出维度={action_size}&#34;)

    def update_target_network(self):
        &#34;&#34;&#34;更新目标网络参数&#34;&#34;&#34;
        self.target_network.load_state_dict(self.q_network.state_dict())

    def remember(self, state, action, reward, next_state, done):
        &#34;&#34;&#34;
        存储经验
        经验回放是DQN成功的关键
        &#34;&#34;&#34;
        self.memory.append((state, action, reward, next_state, done))

    def act(self, state, training=True):
        &#34;&#34;&#34;
        选择动作
        训练时使用ε-贪婪，测试时用贪婪策略
        &#34;&#34;&#34;
        if training and random.random() &lt;= self.epsilon:
            return random.randint(0, self.action_size - 1)

        state_tensor = torch.FloatTensor(state).unsqueeze(0)

        # 不计算梯度，节省计算
        with torch.no_grad():
            q_values = self.q_network(state_tensor)

        return np.argmax(q_values.cpu().numpy())

    def replay(self):
        &#34;&#34;&#34;
        经验回放训练
        这是DQN的核心技巧，打破样本相关性
        &#34;&#34;&#34;
        if len(self.memory) &lt; self.batch_size:
            return

        # 随机采样一批经验
        batch = random.sample(self.memory, self.batch_size)

        # 分离batch数据
        states = torch.FloatTensor([e[0] for e in batch])
        actions = torch.LongTensor([e[1] for e in batch])
        rewards = torch.FloatTensor([e[2] for e in batch])
        next_states = torch.FloatTensor([e[3] for e in batch])
        dones = torch.FloatTensor([e[4] for e in batch])

        # 当前Q值
        current_q_values = self.q_network(states).gather(1, actions.unsqueeze(1))

        # 计算目标Q值（使用目标网络）
        next_q_values = self.target_network(next_states).max(1)[0].detach()
        target_q_values = rewards + (1 - dones) * 0.95 * next_q_values

        # 计算损失
        loss = nn.MSELoss()(current_q_values.squeeze(), target_q_values)

        # 反向传播和优化
        self.optimizer.zero_grad()
        loss.backward()

        # 梯度裁剪，防止梯度爆炸
        torch.nn.utils.clip_grad_norm_(self.q_network.parameters(), 1.0)

        self.optimizer.step()

        # 更新步数
        self.steps += 1

        # 定期更新目标网络
        if self.steps % self.target_update_frequency == 0:
            self.update_target_network()

        # 降低探索率
        if self.epsilon &gt; self.epsilon_min:
            self.epsilon *= self.epsilon_decay

    def save_model(self, filepath: str):
        &#34;&#34;&#34;保存模型&#34;&#34;&#34;
        torch.save({
            &#39;q_network_state&#39;: self.q_network.state_dict(),
            &#39;target_network_state&#39;: self.target_network.state_dict(),
            &#39;optimizer_state&#39;: self.optimizer.state_dict(),
            &#39;epsilon&#39;: self.epsilon,
            &#39;steps&#39;: self.steps
        }, filepath)
        print(f&#34;模型已保存到 {filepath}&#34;)

    def load_model(self, filepath: str):
        &#34;&#34;&#34;加载模型&#34;&#34;&#34;
        checkpoint = torch.load(filepath)
        self.q_network.load_state_dict(checkpoint[&#39;q_network_state&#39;])
        self.target_network.load_state_dict(checkpoint[&#39;target_network_state&#39;])
        self.optimizer.load_state_dict(checkpoint[&#39;optimizer_state&#39;])
        self.epsilon = checkpoint[&#39;epsilon&#39;]
        self.steps = checkpoint[&#39;steps&#39;]
