import uuid
from enum import Enum
import asyncio
import json

class MessageType(Enum):
    &#34;&#34;&#34;消息类型&#34;&#34;&#34;
    REQUEST = &#34;request&#34;
    INFORM = &#34;inform&#34;
    PROPOSE = &#34;propose&#34;
    ACCEPT = &#34;accept&#34;
    REJECT = &#34;reject&#34;
    QUERY = &#34;query&#34;

class Message:
    &#34;&#34;&#34;Agent间通信消息&#34;&#34;&#34;
    def __init__(self, sender: str, receiver: str, 
                 msg_type: MessageType, content: Dict):
        self.id = str(uuid.uuid4())
        self.sender = sender
        self.receiver = receiver
        self.type = msg_type
        self.content = content
        self.timestamp = time.time()

class Task:
    &#34;&#34;&#34;任务定义&#34;&#34;&#34;
    def __init__(self, task_type: str, difficulty: float, 
                 reward: float, deadline: Optional[float] = None):
        self.id = str(uuid.uuid4())
        self.type = task_type
        self.difficulty = difficulty
        self.reward = reward
        self.deadline = deadline
        self.assigned_to = None
        self.status = &#34;pending&#34;
        self.sub_tasks = []  # 支持任务分解

    def decompose(self) -&gt; List[&#39;Task&#39;]:
        &#34;&#34;&#34;任务分解&#34;&#34;&#34;
        if self.difficulty &gt; 5:
            # 复杂任务自动分解
            sub_tasks = []
            remaining_difficulty = self.difficulty

            while remaining_difficulty &gt; 2:
                sub_difficulty = min(3, remaining_difficulty)
                sub_task = Task(
                    self.type,
                    sub_difficulty,
                    self.reward * (sub_difficulty / self.difficulty)
                )
                sub_tasks.append(sub_task)
                remaining_difficulty -= sub_difficulty

            self.sub_tasks = sub_tasks
            return sub_tasks

        return [self]

class CooperativeAgent:
    &#34;&#34;&#34;
    协作型Agent
    支持多种协作协议：合同网、拍卖、协商等
    &#34;&#34;&#34;

    def __init__(self, agent_id: str, skills: List[str], 
                 skill_levels: Optional[Dict[str, float]] = None):
        self.id = agent_id
        self.skills = skills
        self.skill_levels = skill_levels or {s: 1.0 for s in skills}

        # 工作状态
        self.workload = 0.0
        self.max_workload = 1.0

        # 任务管理
        self.current_tasks = []
        self.completed_tasks = []

        # 协作相关
        self.known_agents = {}  # 其他Agent的模型
        self.reputation = 1.0   # 信誉度
        self.trust_scores = {}  # 对其他Agent的信任度

        # 通信
        self.message_queue = asyncio.Queue()

        # 学习参数
        self.learning_rate = 0.1

    async def receive_message(self, message: Message):
        &#34;&#34;&#34;接收消息&#34;&#34;&#34;
        await self.message_queue.put(message)
        print(f&#34;{self.id} 收到来自 {message.sender} 的 {message.type.value} 消息&#34;)

    async def process_messages(self):
        &#34;&#34;&#34;处理消息队列&#34;&#34;&#34;
        while not self.message_queue.empty():
            message = await self.message_queue.get()
            await self.handle_message(message)

    async def handle_message(self, message: Message):
        &#34;&#34;&#34;处理不同类型的消息&#34;&#34;&#34;
        if message.type == MessageType.REQUEST:
            await self.handle_task_request(message)
        elif message.type == MessageType.PROPOSE:
            await self.handle_proposal(message)
        elif message.type == MessageType.QUERY:
            await self.handle_query(message)

    def can_do_task(self, task: Task) -&gt; bool:
        &#34;&#34;&#34;判断是否能完成任务&#34;&#34;&#34;
        # 检查技能匹配
        if task.type not in self.skills:
            return False

        # 检查工作负载
        required_load = task.difficulty * 0.1
        if self.workload + required_load &gt; self.max_workload:
            print(f&#34;{self.id}: 工作负载过高({self.workload:.2f}+{required_load:.2f}&gt;{self.max_workload})&#34;)
            return False

        # 检查截止时间
        if task.deadline:
            estimated_time = task.difficulty / self.skill_levels.get(task.type, 1.0)
            if time.time() + estimated_time &gt; task.deadline:
                print(f&#34;{self.id}: 无法在截止时间前完成&#34;)
                return False

        return True

    def bid_for_task(self, task: Task) -&gt; float:
        &#34;&#34;&#34;
        对任务出价（合同网协议）
        考虑多个因素：技能、负载、信誉等
        &#34;&#34;&#34;
        if not self.can_do_task(task):
            return float(&#39;inf&#39;)

        # 基础成本
        base_cost = task.difficulty * 10

        # 技能因子（技能越高成本越低）
        skill_level = self.skill_levels.get(task.type, 1.0)
        skill_factor = 2.0 - skill_level

        # 负载因子（越忙成本越高）
        load_factor = 1 + self.workload

        # 紧急因子（紧急任务加价）
        urgency_factor = 1.0
        if task.deadline:
            time_left = task.deadline - time.time()
            if time_left &lt; 3600:  # 1小时内
                urgency_factor = 1.5

        # 信誉调整（信誉高可以适当加价）
        reputation_factor = 0.9 + (self.reputation * 0.2)

        final_bid = base_cost * skill_factor * load_factor * urgency_factor * reputation_factor

        print(f&#34;{self.id} 出价: {final_bid:.2f} (技能:{skill_level:.1f}, 负载:{self.workload:.2f}, 信誉:{self.reputation:.2f})&#34;)

        return final_bid

    def negotiate(self, other_agent: &#39;CooperativeAgent&#39;, task: Task) -&gt; Optional[float]:
        &#34;&#34;&#34;
        协商机制
        与其他Agent协商任务分配和价格
        &#34;&#34;&#34;
        my_bid = self.bid_for_task(task)
        other_bid = other_agent.bid_for_task(task)

        if my_bid == float(&#39;inf&#39;) and other_bid == float(&#39;inf&#39;):
            # 都无法独立完成，考虑合作
            return self.propose_collaboration(other_agent, task)

        # 简单的协商策略
        if abs(my_bid - other_bid) &lt; 10:
            # 出价接近，通过信誉决定
            if self.reputation &gt; other_agent.reputation:
                return my_bid * 0.95  # 小幅降价
            else:
                return None

        return None

    def propose_collaboration(self, partner: &#39;CooperativeAgent&#39;, task: Task) -&gt; Optional[float]:
        &#34;&#34;&#34;提议合作&#34;&#34;&#34;
        # 检查技能互补性
        combined_skills = set(self.skills) | set(partner.skills)
        if task.type not in combined_skills:
            return None

        # 计算合作成本
        my_contribution = min(0.5, self.max_workload - self.workload)
        partner_contribution = min(0.5, partner.max_workload - partner.workload)

        if my_contribution + partner_contribution &gt;= task.difficulty * 0.1:
            combined_cost = (self.bid_for_task(task) + partner.bid_for_task(task)) * 0.7  # 合作有优势
            print(f&#34;{self.id} 和 {partner.id} 提议合作，联合出价: {combined_cost:.2f}&#34;)
            return combined_cost

        return None

    def execute_task(self, task: Task) -&gt; bool:
        &#34;&#34;&#34;执行任务&#34;&#34;&#34;
        if task not in self.current_tasks:
            self.current_tasks.append(task)

        # 模拟任务执行
        skill_level = self.skill_levels.get(task.type, 1.0)
        success_rate = min(0.95, 0.5 + skill_level * 0.3 + self.reputation * 0.2)

        success = random.random() &lt; success_rate

        if success:
            # 任务成功
            self.completed_tasks.append(task)
            self.current_tasks.remove(task)

            # 提升技能
            self.skill_levels[task.type] = min(2.0, self.skill_levels[task.type] + 0.05)

            # 提升信誉
            self.reputation = min(1.0, self.reputation + 0.01)

            # 降低负载
            self.workload = max(0, self.workload - task.difficulty * 0.1)

            print(f&#34;{self.id} 成功完成任务 {task.type}&#34;)
            return True
        else:
            # 任务失败
            self.reputation = max(0, self.reputation - 0.05)
            print(f&#34;{self.id} 任务失败 {task.type}&#34;)
            return False

    def learn_from_others(self, other_agent: &#39;CooperativeAgent&#39;):
        &#34;&#34;&#34;
        从其他Agent学习
        知识传递机制
        &#34;&#34;&#34;
        for skill in other_agent.skills:
            if skill not in self.skills:
                # 学习新技能
                if random.random() &lt; self.learning_rate:
                    self.skills.append(skill)
                    self.skill_levels[skill] = 0.3  # 初始水平较低
                    print(f&#34;{self.id} 从 {other_agent.id} 学会了 {skill}&#34;)
            elif skill in self.skills:
                # 提升现有技能
                other_level = other_agent.skill_levels.get(skill, 1.0)
                my_level = self.skill_levels.get(skill, 1.0)

                if other_level &gt; my_level:
                    improvement = (other_level - my_level) * self.learning_rate
                    self.skill_levels[skill] = min(2.0, my_level + improvement)
                    print(f&#34;{self.id} 提升了 {skill} 技能到 {self.skill_levels[skill]:.2f}&#34;)

class MultiAgentSystem:
    &#34;&#34;&#34;
    多Agent系统协调器
    负责任务分配、协调和系统管理

    支持多种协调机制：
    1. 合同网协议（Contract Net Protocol）
    2. 拍卖机制（Auction）
    3. 黑板系统（Blackboard）
    4. 团队形成（Team Formation）
    &#34;&#34;&#34;

    def __init__(self, coordination_type: str = &#34;contract_net&#34;):
        self.agents: Dict[str, CooperativeAgent] = {}
        self.tasks: List[Task] = []
        self.completed_tasks: List[Task] = []
        self.coordination_type = coordination_type

        # 黑板系统（共享知识库）
        self.blackboard = {
            &#39;tasks&#39;: [],
            &#39;solutions&#39;: [],
            &#39;knowledge&#39;: {}
        }

        # 系统指标
        self.metrics = {
            &#39;total_tasks&#39;: 0,
            &#39;completed_tasks&#39;: 0,
            &#39;failed_tasks&#39;: 0,
            &#39;total_reward&#39;: 0,
            &#39;average_completion_time&#39;: 0,
            &#39;cooperation_count&#39;: 0
        }

    def add_agent(self, agent: CooperativeAgent):
        &#34;&#34;&#34;添加Agent到系统&#34;&#34;&#34;
        self.agents[agent.id] = agent

        # 让Agent互相认识
        for other_id, other_agent in self.agents.items():
            if other_id != agent.id:
                agent.known_agents[other_id] = other_agent
                other_agent.known_agents[agent.id] = agent

        print(f&#34;Agent {agent.id} 加入系统，技能: {agent.skills}&#34;)

    async def assign_task_contract_net(self, task: Task) -&gt; bool:
        &#34;&#34;&#34;
        使用合同网协议分配任务
        这是最经典的多Agent协调机制
        &#34;&#34;&#34;
        print(f&#34;\n[合同网] 发布任务: {task.type} (难度:{task.difficulty}, 奖励:{task.reward})&#34;)

        # 1. 任务公告
        bids = {}
        for agent_id, agent in self.agents.items():
            bid = agent.bid_for_task(task)
            if bid != float(&#39;inf&#39;):
                bids[agent_id] = bid

        if not bids:
            # 没有Agent能独立完成，尝试分解任务
            sub_tasks = task.decompose()
            if len(sub_tasks) &gt; 1:
                print(f&#34;  任务分解为 {len(sub_tasks)} 个子任务&#34;)
                for sub_task in sub_tasks:
                    await self.assign_task_contract_net(sub_task)
                return True
            else:
                print(&#34;  没有Agent能完成此任务&#34;)
                self.metrics[&#39;failed_tasks&#39;] += 1
                return False

        # 2. 投标评估和选择
        winner_id = min(bids, key=bids.get)
        winner = self.agents[winner_id]

        # 3. 合同授予
        task.assigned_to = winner_id
        task.status = &#34;assigned&#34;
        winner.current_tasks.append(task)
        winner.workload += task.difficulty * 0.1

        print(f&#34;任务分配给 {winner_id}，中标价: {bids[winner_id]:.2f}&#34;)

        self.metrics[&#39;total_tasks&#39;] += 1
        return True

    def form_team(self, task: Task) -&gt; Optional[List[CooperativeAgent]]:
        &#34;&#34;&#34;
        团队形成算法
        为复杂任务组建最佳团队
        &#34;&#34;&#34;
        required_skills = [task.type]  # 简化：假设任务只需要一种技能

        # 找出所有可能的团队组合
        potential_teams = []

        for size in range(2, min(4, len(self.agents) + 1)):  # 团队大小2-3人
            from itertools import combinations

            for combo in combinations(self.agents.values(), size):
                team_skills = set()
                team_load = 0
                team_cost = 0

                for agent in combo:
                    team_skills.update(agent.skills)
                    team_load += agent.workload
                    team_cost += agent.bid_for_task(task)

                # 检查团队是否满足要求
                if all(skill in team_skills for skill in required_skills):
                    if team_load / size &lt; 0.7:  # 平均负载不太高
                        potential_teams.append({
                            &#39;members&#39;: combo,
                            &#39;cost&#39;: team_cost,
                            &#39;efficiency&#39;: sum(a.skill_levels.get(task.type, 0) for a in combo)
                        })

        if not potential_teams:
            return None

        # 选择最佳团队（成本效益比）
        best_team = min(potential_teams, key=lambda t: t[&#39;cost&#39;] / t[&#39;efficiency&#39;])

        print(f&#34;组建团队: {[a.id for a in best_team[&#39;members&#39;]]}&#34;)
        return best_team[&#39;members&#39;]

    def share_knowledge(self):
        &#34;&#34;&#34;
        知识共享机制
        Agent之间分享经验和技能
        &#34;&#34;&#34;
        for agent_id, agent in self.agents.items():
            # 找到可以学习的对象
            for other_id, other_agent in self.agents.items():
                if other_id != agent_id:
                    # 基于信任度决定是否学习
                    trust = agent.trust_scores.get(other_id, 0.5)
                    if random.random() &lt; trust:
                        agent.learn_from_others(other_agent)

    def update_trust(self):
        &#34;&#34;&#34;更新Agent间的信任度&#34;&#34;&#34;
        for agent in self.agents.values():
            for other_id, other_agent in agent.known_agents.items():
                # 基于合作历史更新信任
                if other_agent.reputation &gt; 0.8:
                    agent.trust_scores[other_id] = min(1.0, agent.trust_scores.get(other_id, 0.5) + 0.1)
                elif other_agent.reputation &lt; 0.3:
                    agent.trust_scores[other_id] = max(0, agent.trust_scores.get(other_id, 0.5) - 0.1)

    async def run_round(self):
        &#34;&#34;&#34;运行一轮系统&#34;&#34;&#34;
        # 分配任务
        for task in self.tasks[:]:
            if task.status == &#34;pending&#34;:
                if self.coordination_type == &#34;contract_net&#34;:
                    success = await self.assign_task_contract_net(task)
                    if success:
                        self.tasks.remove(task)

        # 执行任务
        for agent in self.agents.values():
            for task in agent.current_tasks[:]:
                if agent.execute_task(task):
                    self.completed_tasks.append(task)
                    self.metrics[&#39;completed_tasks&#39;] += 1
                    self.metrics[&#39;total_reward&#39;] += task.reward

        # 知识共享
        if random.random() &lt; 0.3:  # 30%概率进行知识共享
            self.share_knowledge()

        # 更新信任度
        self.update_trust()

        # Agent休息（降低负载）
        for agent in self.agents.values():
            agent.workload = max(0, agent.workload - 0.05)

    def get_statistics(self):
        &#34;&#34;&#34;获取系统统计信息&#34;&#34;&#34;
        print(&#34;\n=== 系统统计 ===&#34;)
        print(f&#34;总任务数: {self.metrics[&#39;total_tasks&#39;]}&#34;)
        print(f&#34;完成任务: {self.metrics[&#39;completed_tasks&#39;]}&#34;)
        print(f&#34;失败任务: {self.metrics[&#39;failed_tasks&#39;]}&#34;)
        print(f&#34;总收益: {self.metrics[&#39;total_reward&#39;]}&#34;)

        if self.metrics[&#39;completed_tasks&#39;] &gt; 0:
            print(f&#34;平均任务价值: {self.metrics[&#39;total_reward&#39;]/self.metrics[&#39;completed_tasks&#39;]:.2f}&#34;)

        print(&#34;\n=== Agent状态 ===&#34;)
        for agent_id, agent in self.agents.items():
            print(f&#34;{agent_id}:&#34;)
            print(f&#34;  技能: {agent.skills}&#34;)
            print(f&#34;  技能等级: {agent.skill_levels}&#34;)
            print(f&#34;  当前负载: {agent.workload:.2f}&#34;)
            print(f&#34;  信誉度: {agent.reputation:.2f}&#34;)
            print(f&#34;  完成任务: {len(agent.completed_tasks)}&#34;)

