        CooperativeAgent(&#34;全栈新手&#34;, [&#34;backend&#34;, &#34;frontend&#34;], 
                        {&#34;backend&#34;: 0.8, &#34;frontend&#34;: 0.7}),
        CooperativeAgent(&#34;AI专家&#34;, [&#34;machine_learning&#34;, &#34;data_analysis&#34;], 
                        {&#34;machine_learning&#34;: 2.0, &#34;data_analysis&#34;: 1.6})
    ]

    for agent in agents:
