    loads = [agent.workload for agent in system.agents.values()]
    avg_load = sum(loads) / len(loads)
    load_variance = sum((l - avg_load) ** 2 for l in loads) / len(loads)

    print(f&#34;平均负载: {avg_load:.3f}&#34;)
    print(f&#34;负载方差: {load_variance:.3f}&#34;)
    print(f&#34;负载均衡度: {&#39;优秀&#39; if load_variance &lt; 0.01 else &#39;良好&#39; if load_variance &lt; 0.05 else &#39;需改进&#39;}&#34;)

    # 计算技能提升
    total_skill_improvement = 0
    for agent in system.agents.values():
        for skill, level in agent.skill_levels.items():
            total_skill_improvement += max(0, level - 1.0)  # 相对初始水平的提升

    print(f&#34;总技能提升: {total_skill_improvement:.2f}&#34;)
    print(f&#34;平均信誉度: {sum(a.reputation for a in system.agents.values()) / len(system.agents):.2f}&#34;)

