class MemoryEfficientAgent:
    &#34;&#34;&#34;内存优化版Agent&#34;&#34;&#34;

    def __init__(self):
        # 用deque限制大小，自动丢弃老数据
        self.short_memory = deque(maxlen=1000)

        # 长期记忆用弱引用
        self.long_memory = weakref.WeakValueDictionary()

        # 定期清理计数器
        self.cleanup_counter = 0

        # 内存使用监控
        self.memory_limit = 1024 * 1024 * 512  # 512MB

    def add_memory(self, key, item):
        &#34;&#34;&#34;添加记忆项&#34;&#34;&#34;
        # 短期记忆
        self.short_memory.append(item)

        # 长期记忆（自动垃圾回收）
        if self._is_important(item):
            self.long_memory[key] = item

        # 定期清理
        self.cleanup_counter += 1
        if self.cleanup_counter &gt;= 100:
            self._cleanup()
            self.cleanup_counter = 0

    def _is_important(self, item):
        &#34;&#34;&#34;判断是否值得长期记忆&#34;&#34;&#34;
        # 实现重要性评估逻辑
        return item.get(&#39;importance&#39;, 0) &gt; 0.7

    def _cleanup(self):
        &#34;&#34;&#34;内存清理&#34;&#34;&#34;
        # 检查内存使用
        current_memory = self._get_memory_usage()

        if current_memory &gt; self.memory_limit:
            # 清理最旧的50%短期记忆
            for _ in range(len(self.short_memory) // 2):
                self.short_memory.popleft()

            # 强制垃圾回收
            gc.collect()

            print(f&#34;内存清理完成: {current_memory/1024/1024:.2f}MB -&gt; {self._get_memory_usage()/1024/1024:.2f}MB&#34;)

    def _get_memory_usage(self):
        &#34;&#34;&#34;获取当前内存使用量&#34;&#34;&#34;
        return sum(sys.getsizeof(obj) for obj in gc.get_objects())训练速度慢使用向量化操作和批处理：import numpy as np
