class MonitoredAgent:
    &#34;&#34;&#34;带监控的Agent&#34;&#34;&#34;

    # Prometheus指标
    perception_counter = Counter(&#39;agent_perceptions_total&#39;, &#39;Total perceptions&#39;, [&#39;agent_id&#39;])
    decision_time = Histogram(&#39;agent_decision_duration_seconds&#39;, &#39;Decision time&#39;, [&#39;agent_id&#39;])
    action_counter = Counter(&#39;agent_actions_total&#39;, &#39;Total actions&#39;, [&#39;agent_id&#39;, &#39;action_type&#39;])
    current_workload = Gauge(&#39;agent_workload&#39;, &#39;Current workload&#39;, [&#39;agent_id&#39;])
    error_counter = Counter(&#39;agent_errors_total&#39;, &#39;Total errors&#39;, [&#39;agent_id&#39;, &#39;error_type&#39;])

    def __init__(self, agent_id: str):
        self.agent_id = agent_id

        # 结构化日志
        self.logger = self._setup_logger()

        # 启动Prometheus metrics服务
        start_http_server(8081)

    def _setup_logger(self):
        &#34;&#34;&#34;设置结构化日志&#34;&#34;&#34;
        logger = logging.getLogger(f&#34;agent.{self.agent_id}&#34;)
        logger.setLevel(logging.INFO)

        # JSON格式处理器
        handler = logging.StreamHandler()
        handler.setFormatter(JsonFormatter())
        logger.addHandler(handler)

        return logger

    def perceive(self, environment):
        &#34;&#34;&#34;带监控的感知&#34;&#34;&#34;
        self.perception_counter.labels(agent_id=self.agent_id).inc()

        start_time = time.time()
        try:
            result = self._do_perceive(environment)

            self.logger.info(&#34;perception_complete&#34;, extra={
                &#39;agent_id&#39;: self.agent_id,
                &#39;duration&#39;: time.time() - start_time,
                &#39;result_size&#39;: len(str(result))
            })

            return result
        except Exception as e:
            self.error_counter.labels(
                agent_id=self.agent_id,
                error_type=&#39;perception_error&#39;
            ).inc()

            self.logger.error(&#34;perception_failed&#34;, extra={
                &#39;agent_id&#39;: self.agent_id,
                &#39;error&#39;: str(e)
            })
            raise

    def decide(self, percept):
        &#34;&#34;&#34;带监控的决策&#34;&#34;&#34;
        with self.decision_time.labels(agent_id=self.agent_id).time():
            decision = self._do_decide(percept)

        self.action_counter.labels(
            agent_id=self.agent_id,
            action_type=decision[&#39;action&#39;]
        ).inc()

        return decision

    def update_workload(self, workload):
        &#34;&#34;&#34;更新工作负载指标&#34;&#34;&#34;
        self.current_workload.labels(agent_id=self.agent_id).set(workload)

class JsonFormatter(logging.Formatter):
    &#34;&#34;&#34;JSON日志格式化器&#34;&#34;&#34;

    def format(self, record):
        log_obj = {
            &#39;timestamp&#39;: self.formatTime(record),
            &#39;level&#39;: record.levelname,
            &#39;logger&#39;: record.name,
            &#39;message&#39;: record.getMessage(),
        }

        # 添加额外字段
        if hasattr(record, &#39;extra&#39;):
            log_obj.update(record.extra)

        return json.dumps(log_obj)学习资源推荐（都是我看过觉得有用的）学Agent是个长期过程，这些资源对我帮助很大：必读书籍Russell &amp; Norvig《人工智能：一种现代方法》第4版[1] Agent理论的圣经，第2章专门讲Agent推荐理由：理论扎实，例子丰富在线资源：Artificial Intelligence: A Modern Approach, 4th US ed.Sutton &amp; Barto《强化学习》第2版[5] 强化学习必读，Agent学习的基础推荐理由：从基础到前沿，循序渐进免费PDF：Reinforcement Learning: An IntroductionWooldridge《多Agent系统引论》第2版[4] 多Agent协作的权威教材推荐理由：涵盖所有主要协议和架构Shoham &amp; Leyton-Brown《多Agent系统：算法、博弈与逻辑基础》偏理论但很深入推荐理由：如果你想深入理解Agent的数学基础开源项目（强烈推荐）OpenAI Gym[6] 强化学习环境，练手必备我的建议：从CartPole开始，逐步挑战Atari游戏Ray RLLib[7] 分布式强化学习框架适合场景：大规模Agent训练PettingZoo[8] 多Agent强化学习环境特色：各种多Agent游戏和场景LangChain + AutoGen[9] [10]：LLM Agent框架，结合大模型做AgentJADE (Java Agent DEvelopment Framework)[11] 经典的Agent开发框架适合：企业级多Agent系统重要论文（看懂这几篇就入门了）“Deep Reinforcement Learning: An Overview” (Li, 2018)[12]：深度强化学习综述，必读“Human-level control through deep reinforcement learning” (Mnih et al., 2015)[3] Nature论文，DQN的开山之作DOI: 10.1038/nature14236“Multi-Agent Reinforcement Learning: A Selective Overview” (Zhang et al., 2021)[13]：多Agent RL最新综述“BDI Agents: From Theory to Practice” (Rao &amp; Georgeff, 1995)[2] BDI架构经典论文理解Agent认知架构必读“Attention Is All You Need” (Vaswani et al., 2017)[14]：Transformer架构，现代LLM Agent的基础CS285: Deep Reinforcement Learning (UC Berkeley)[15]:Sergey Levine的课，质量极高实用工具和平台Weights &amp; Biases (wandb)[16]:实验跟踪，调参必备TensorBoard:训练可视化,配合PyTorch/TensorFlow使用MLflow[17]:模型管理和部署最近半年，我一直在探索Agent与大模型的结合。很多人以为Agent= LLM，其实并不是。LLM-Powered Agent架构import openai
