            return self._fallback_decision(messages[-1][&#39;content&#39;])

    def _build_context(self, situation: str) -&gt; str:
        &#34;&#34;&#34;构建上下文信息&#34;&#34;&#34;
        # 从记忆中检索相关信息
        relevant_memories = self._retrieve_relevant_memories(situation)

        # 构建上下文字符串
        context_parts = []

        if relevant_memories:
            context_parts.append(&#34;相关历史经验：&#34;)
            for memory in relevant_memories[-5:]:  # 最近5条
                context_parts.append(f&#34;- {memory[&#39;summary&#39;]}&#34;)

        if self.knowledge_base:
            context_parts.append(&#34;\n当前知识：&#34;)
            for key, value in list(self.knowledge_base.items())[:5]:
                context_parts.append(f&#34;- {key}: {value}&#34;)

        return &#34;\n&#34;.join(context_parts)

    def _retrieve_relevant_memories(self, query: str) -&gt; List[Dict]:
        &#34;&#34;&#34;检索相关记忆&#34;&#34;&#34;
        # 简单的关键词匹配，实际可以用向量数据库
        relevant = []

        keywords = set(query.lower().split())
        for memory in self.memory:
            memory_keywords = set(memory.get(&#39;summary&#39;, &#39;&#39;).lower().split())
            if keywords &amp; memory_keywords:  # 有交集
                relevant.append(memory)

        return relevant

    async def decide_with_reasoning(self, situation: str) -&gt; Dict:
        &#34;&#34;&#34;
        结合LLM推理和传统决策
        &#34;&#34;&#34;
        # 1. LLM高级推理
        llm_thoughts = await self.think(situation)

        # 2. 传统Agent决策
        traditional_decision = self.executor.decide(situation)

        # 3. 综合决策
        final_decision = self._combine_decisions(llm_thoughts, traditional_decision)

        # 4. 记录决策过程
        self.memory.append({
            &#39;situation&#39;: situation,
            &#39;llm_analysis&#39;: llm_thoughts,
            &#39;traditional&#39;: traditional_decision,
            &#39;final&#39;: final_decision,
            &#39;timestamp&#39;: time.time()
        })

        return final_decision

    def _combine_decisions(self, llm_thoughts: Dict, traditional: Dict) -&gt; Dict:
        &#34;&#34;&#34;
        综合LLM和传统决策
        这是关键：如何平衡创造性和可靠性
        &#34;&#34;&#34;
        # 如果LLM建议的动作是可执行的，优先采用
        if llm_thoughts.get(&#39;confidence&#39;, 0) &gt; 0.8:
            return llm_thoughts

        # 如果传统方法有高置信度，使用传统方法
        if traditional.get(&#39;confidence&#39;, 0) &gt; 0.9:
            return traditional

        # 否则，结合两者
        return {
            &#39;action&#39;: llm_thoughts.get(&#39;action&#39;, traditional.get(&#39;action&#39;)),
            &#39;reasoning&#39;: llm_thoughts.get(&#39;reasoning&#39;, &#39;&#39;),
            &#39;parameters&#39;: traditional.get(&#39;parameters&#39;, {}),
            &#39;confidence&#39;: (llm_thoughts.get(&#39;confidence&#39;, 0) + traditional.get(&#39;confidence&#39;, 0)) / 2
        }

    async def learn_from_feedback(self, outcome: Dict):
        &#34;&#34;&#34;
        从结果中学习
        利用LLM的反思能力
        &#34;&#34;&#34;
        # 构建反思提示
        reflection_prompt = f&#34;&#34;&#34;
        执行的动作：{outcome[&#39;action&#39;]}
        预期结果：{outcome[&#39;expected&#39;]}
        实际结果：{outcome[&#39;actual&#39;]}

        请分析：
        1. 为什么会出现这个结果？
        2. 有什么可以改进的地方？
        3. 应该记住什么经验教训？
        &#34;&#34;&#34;

        # 让LLM反思
        reflection = await self._call_llm([
            {&#34;role&#34;: &#34;system&#34;, &#34;content&#34;: &#34;你是一个善于反思和学习的Agent。&#34;},
            {&#34;role&#34;: &#34;user&#34;, &#34;content&#34;: reflection_prompt}
        ])

        # 提取经验教训
        lessons = self._extract_lessons(reflection)

        # 更新知识库
        for lesson in lessons:
            self.knowledge_base[lesson[&#39;key&#39;]] = lesson[&#39;value&#39;]

        print(f&#34;学到了 {len(lessons)} 条经验&#34;)Agent + LLM的优势自然语言理解：LLM让Agent能理解复杂的人类指令常识推理：不需要手动编码所有规则适应性强：能处理未见过的情况可解释性：能用自然语言解释决策过程但是，LLM-Agent还面临很多挑战：响应速度慢LLM API调用延迟高（通常&gt;1秒）不适合实时控制场景成本问题GPT-4 API很贵高频决策成本不可接受幻觉问题 LLM可能生成错误信息需要验证机制可控性差 输出不确定性高难以保证安全边界混合架构：最佳实践基于实践，我认为混合架构是目前最好的方案：class HybridAgent:
    &#34;&#34;&#34;
    混合架构Agent
    快速反应用传统方法，复杂决策用LLM
    &#34;&#34;&#34;

    def __init__(self):
        # 分层决策系统
        self.reflex_layer = ReflexAgent()      # 反射层：毫秒级
        self.tactical_layer = PlanningAgent()   # 战术层：秒级
        self.strategic_layer = LLMAgent()       # 战略层：分钟级

    async def decide(self, situation):
        urgency = self.assess_urgency(situation)

        if urgency == &#34;immediate&#34;:
            # 紧急情况，立即反应
            return self.reflex_layer.react(situation)

        elif urgency == &#34;tactical&#34;:
            # 需要短期规划
            return await self.tactical_layer.plan(situation)

        else:
            # 复杂决策，调用LLM
            return await self.strategic_layer.deliberate(situation)Agent：eg.ant，Agent成为了蚁工常备工具搞了这么多年Agent，最大的感受是：Agent不是万能的，但没有Agent是万万不能的。选择Agent架构的决策框架什么时候该用Agent？我总结了个决策树：基于踩过的坑，几点建议：从简单开始：先实现反应式Agent，再逐步添加学习能力重视监控：生产环境必须有完善的监控和日志混合方案：结合传统方法和AI方法，取长补短持续学习：Agent领域发展很快，保持学习注重实效：不要为了用Agent而用Agent做Agent，我们不是在&#34;创造&#34;智能，而是在&#34;培育&#34;智能。就像园丁培育植物，我们提供环境、规则和反馈，然后看着Agent自己成长。有时候Agent会做出让你惊讶的决策，那种感觉很奇妙。记得有次一个游戏Agent发现了我都没想到的通关策略，那一刻我真的感受到了&#34;智能&#34;的存在。当然，现在的Agent离真正的AGI还很远。也许再过10年、20年，我们真的能看到像科幻电影里那样的智能Agent。希望这篇分享对你有帮助。Agent的水很深，但也很有趣。如果你也在做Agent，欢迎交流。如果你刚开始学，记住：保持好奇心，多动手实践，不要怕失败。
